def _acyclic(graph):
    state = {}

    def visit(name):
        mark = state.get(name, 0)
        if mark == 1:
            return False
        if mark == 2:
            return True

        state[name] = 1
        for dependency in graph.get(name, ()):
            if dependency in graph and not visit(dependency):
                return False
        state[name] = 2
        return True

    for name in graph:
        if state.get(name, 0) == 0 and not visit(name):
            return False
    return True


